public static void lookupFilteredByTAMRebateCompanyPolicy(FormControl _control)
{
    // Build list of allowed companies first
    METUserSecurityGroupList groupList;
    METUserSecurityRebateCompanyList companyList;
    str rangeValue = '';

    while select RebateCompanyId from companyList
      exists join groupList
          where groupList.UserSecurityGroupId == companyList.UserSecurityGroupId
             && groupList.UserId == curUserId()
    {
        if (rangeValue)
        {
            rangeValue += ',';
        }
        rangeValue += companyList.RebateCompanyId;
    }

    Query query = new Query();
    QueryBuildDataSource qbdsCompany = query.addDataSource(tableNum(CompanyInfo));

    if (rangeValue)
    {
        qbdsCompany.addRange(fieldNum(CompanyInfo, DataArea)).value(rangeValue);
    }
    else
    {
        qbdsCompany.addRange(fieldNum(CompanyInfo, DataArea)).value(SysQuery::valueEmptyString());
    }

    SysTableLookup lookup = SysTableLookup::newParameters(tableNum(CompanyInfo), _control);
    lookup.addLookupField(fieldNum(CompanyInfo, DataArea));
    lookup.addLookupField(fieldNum(CompanyInfo, Name));
    lookup.parmQuery(query);
    lookup.performFormLookup();
}
